// ============================================================
// Data Models
// ============================================================

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

// ============================================================
// Event Bus Contract
// ============================================================

export interface IEventBus {
  publish(event: string, payload: unknown): void;
  subscribe(event: string, callback: (payload: unknown) => void): void;
}

// Event payloads
export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

// ============================================================
// Service Contracts
// ============================================================

export interface IUserService {
  create(input: { name: string; email: string }): User;
  getById(id: string): User;
  getAll(): User[];
  update(id: string, input: Partial<{ name: string; email: string }>): User;
  delete(id: string): void;
}

export interface IProjectService {
  create(input: { name: string; description: string }): Project;
  getById(id: string): Project;
  getAll(): Project[];
  update(id: string, input: Partial<{ name: string; description: string }>): Project;
  delete(id: string): void;
  addMember(projectId: string, userId: string): Project;
  removeMember(projectId: string, userId: string): Project;
}

export interface ITaskService {
  create(input: { title: string; description: string; projectId: string }): Task;
  getById(id: string): Task;
  getByProject(projectId: string): Task[];
  update(id: string, input: Partial<{ title: string; description: string }>): Task;
  delete(id: string): void;
  assign(taskId: string, assigneeId: string): Task;
  changeStatus(taskId: string, newStatus: TaskStatus): Task;
}

export interface ICommentService {
  create(input: { taskId: string; authorId: string; body: string }): Comment;
  getById(id: string): Comment;
  getByTask(taskId: string): Comment[];
  delete(id: string): void;
}

export interface INotificationService {
  getByUser(userId: string): Notification[];
  markAsRead(notificationId: string): Notification;
}

import { IEventBus } from "./types.js";

export class EventBus implements IEventBus {
  private subscribers: Map<string, Array<(payload: unknown) => void>> = new Map();

  publish(event: string, payload: unknown): void {
    const handlers = this.subscribers.get(event);
    if (!handlers || handlers.length === 0) {
      return;
    }
    for (const handler of handlers) {
      try {
        handler(payload);
      } catch (err) {
        console.error(`[EventBus] Error in handler for event "${event}":`, err);
      }
    }
  }

  subscribe(event: string, callback: (payload: unknown) => void): void {
    const existing = this.subscribers.get(event);
    if (existing) {
      existing.push(callback);
    } else {
      this.subscribers.set(event, [callback]);
    }
  }
}

import { randomUUID } from "crypto";
import { IUserService, User } from "../types.js";

export class UserService implements IUserService {
  private store: Map<string, User> = new Map();

  create(input: { name: string; email: string }): User {
    const user: User = {
      id: randomUUID(),
      name: input.name,
      email: input.email,
    };
    this.store.set(user.id, user);
    return { ...user };
  }

  getById(id: string): User {
    const user = this.store.get(id);
    if (!user) {
      throw new Error(`User not found: ${id}`);
    }
    return { ...user };
  }

  getAll(): User[] {
    return Array.from(this.store.values()).map((u) => ({ ...u }));
  }

  update(id: string, input: Partial<{ name: string; email: string }>): User {
    const user = this.store.get(id);
    if (!user) {
      throw new Error(`User not found: ${id}`);
    }
    if (input.name !== undefined) user.name = input.name;
    if (input.email !== undefined) user.email = input.email;
    this.store.set(id, user);
    return { ...user };
  }

  delete(id: string): void {
    if (!this.store.has(id)) {
      throw new Error(`User not found: ${id}`);
    }
    this.store.delete(id);
  }
}

import { randomUUID } from "crypto";
import { IProjectService, Project } from "../types.js";

export class ProjectService implements IProjectService {
  private store: Map<string, Project> = new Map();

  create(input: { name: string; description: string }): Project {
    const project: Project = {
      id: randomUUID(),
      name: input.name,
      description: input.description,
      memberIds: [],
    };
    this.store.set(project.id, project);
    return this.clone(project);
  }

  getById(id: string): Project {
    const project = this.store.get(id);
    if (!project) {
      throw new Error(`Project not found: ${id}`);
    }
    return this.clone(project);
  }

  getAll(): Project[] {
    return Array.from(this.store.values()).map((p) => this.clone(p));
  }

  update(id: string, input: Partial<{ name: string; description: string }>): Project {
    const project = this.store.get(id);
    if (!project) {
      throw new Error(`Project not found: ${id}`);
    }
    if (input.name !== undefined) project.name = input.name;
    if (input.description !== undefined) project.description = input.description;
    this.store.set(id, project);
    return this.clone(project);
  }

  delete(id: string): void {
    if (!this.store.has(id)) {
      throw new Error(`Project not found: ${id}`);
    }
    this.store.delete(id);
  }

  addMember(projectId: string, userId: string): Project {
    const project = this.store.get(projectId);
    if (!project) {
      throw new Error(`Project not found: ${projectId}`);
    }
    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
    }
    this.store.set(projectId, project);
    return this.clone(project);
  }

  removeMember(projectId: string, userId: string): Project {
    const project = this.store.get(projectId);
    if (!project) {
      throw new Error(`Project not found: ${projectId}`);
    }
    project.memberIds = project.memberIds.filter((id) => id !== userId);
    this.store.set(projectId, project);
    return this.clone(project);
  }

  private clone(project: Project): Project {
    return { ...project, memberIds: [...project.memberIds] };
  }
}

import { randomUUID } from "crypto";
import { IEventBus, ITaskService, Task, TaskStatus } from "../types.js";

// Forward-only status transition map
const STATUS_ORDER: Record<TaskStatus, number> = {
  "todo": 0,
  "in-progress": 1,
  "done": 2,
};

export class TaskService implements ITaskService {
  private store: Map<string, Task> = new Map();
  private eventBus: IEventBus;

  constructor(eventBus: IEventBus) {
    this.eventBus = eventBus;
  }

  create(input: { title: string; description: string; projectId: string }): Task {
    const task: Task = {
      id: randomUUID(),
      title: input.title,
      description: input.description,
      status: "todo",
      assigneeId: null,
      projectId: input.projectId,
    };
    this.store.set(task.id, task);
    return { ...task };
  }

  getById(id: string): Task {
    const task = this.store.get(id);
    if (!task) {
      throw new Error(`Task not found: ${id}`);
    }
    return { ...task };
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values())
      .filter((t) => t.projectId === projectId)
      .map((t) => ({ ...t }));
  }

  update(id: string, input: Partial<{ title: string; description: string }>): Task {
    const task = this.store.get(id);
    if (!task) {
      throw new Error(`Task not found: ${id}`);
    }
    if (input.title !== undefined) task.title = input.title;
    if (input.description !== undefined) task.description = input.description;
    this.store.set(id, task);
    return { ...task };
  }

  delete(id: string): void {
    if (!this.store.has(id)) {
      throw new Error(`Task not found: ${id}`);
    }
    this.store.delete(id);
  }

  assign(taskId: string, assigneeId: string): Task {
    const task = this.store.get(taskId);
    if (!task) {
      throw new Error(`Task not found: ${taskId}`);
    }
    task.assigneeId = assigneeId;
    this.store.set(taskId, task);

    this.eventBus.publish("task.assigned", {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: assigneeId,
    });

    return { ...task };
  }

  changeStatus(taskId: string, newStatus: TaskStatus): Task {
    const task = this.store.get(taskId);
    if (!task) {
      throw new Error(`Task not found: ${taskId}`);
    }

    const currentOrder = STATUS_ORDER[task.status];
    const newOrder = STATUS_ORDER[newStatus];

    if (newOrder !== currentOrder + 1) {
      throw new Error(
        `Invalid status transition: "${task.status}" → "${newStatus}". ` +
        `Only sequential forward transitions are allowed (todo → in-progress → done).`
      );
    }

    const oldStatus = task.status;
    task.status = newStatus;
    this.store.set(taskId, task);

    this.eventBus.publish("task.statusChanged", {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus: oldStatus,
      newStatus: newStatus,
    });

    return { ...task };
  }
}

import { randomUUID } from "crypto";
import { Comment, ICommentService, IEventBus } from "../types.js";

export class CommentService implements ICommentService {
  private store: Map<string, Comment> = new Map();
  private eventBus: IEventBus;

  // authorName resolver injected to avoid cross-service imports
  private resolveAuthorName: (authorId: string) => string;

  // taskTitle resolver injected to avoid cross-service imports
  private resolveTaskTitle: (taskId: string) => string;

  constructor(
    eventBus: IEventBus,
    resolveAuthorName: (authorId: string) => string,
    resolveTaskTitle: (taskId: string) => string
  ) {
    this.eventBus = eventBus;
    this.resolveAuthorName = resolveAuthorName;
    this.resolveTaskTitle = resolveTaskTitle;
  }

  create(input: { taskId: string; authorId: string; body: string }): Comment {
    const comment: Comment = {
      id: randomUUID(),
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body,
      createdAt: new Date().toISOString(),
    };
    this.store.set(comment.id, comment);

    const authorName = this.resolveAuthorName(input.authorId);
    const taskTitle = this.resolveTaskTitle(input.taskId);

    this.eventBus.publish("comment.added", {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle: taskTitle,
      authorId: comment.authorId,
      authorName: authorName,
    });

    return { ...comment };
  }

  getById(id: string): Comment {
    const comment = this.store.get(id);
    if (!comment) {
      throw new Error(`Comment not found: ${id}`);
    }
    return { ...comment };
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values())
      .filter((c) => c.taskId === taskId)
      .map((c) => ({ ...c }));
  }

  delete(id: string): void {
    if (!this.store.has(id)) {
      throw new Error(`Comment not found: ${id}`);
    }
    this.store.delete(id);
  }
}

import { randomUUID } from "crypto";
import {
  CommentAddedPayload,
  IEventBus,
  INotificationService,
  Notification,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
} from "../types.js";

export class NotificationService implements INotificationService {
  private store: Map<string, Notification> = new Map();

  // taskAssignee resolver injected to avoid cross-service imports
  private resolveTaskAssigneeId: (taskId: string) => string | null;

  constructor(
    eventBus: IEventBus,
    resolveTaskAssigneeId: (taskId: string) => string | null
  ) {
    this.resolveTaskAssigneeId = resolveTaskAssigneeId;

    eventBus.subscribe("task.assigned", (payload) => {
      const p = payload as TaskAssignedPayload;
      this.createNotification(
        p.assigneeId,
        `Task '${p.taskTitle}' assigned to you`
      );
    });

    eventBus.subscribe("task.statusChanged", (payload) => {
      const p = payload as TaskStatusChangedPayload;
      if (p.assigneeId) {
        this.createNotification(
          p.assigneeId,
          `Task '${p.taskTitle}' status changed to ${p.newStatus}`
        );
      }
    });

    eventBus.subscribe("comment.added", (payload) => {
      const p = payload as CommentAddedPayload;
      const assigneeId = this.resolveTaskAssigneeId(p.taskId);
      if (assigneeId && assigneeId !== p.authorId) {
        this.createNotification(
          assigneeId,
          `${p.authorName} commented on task '${p.taskTitle}'`
        );
      }
    });
  }

  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(notification.id, notification);
    return notification;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values())
      .filter((n) => n.userId === userId)
      .map((n) => ({ ...n }));
  }

  markAsRead(notificationId: string): Notification {
    const notification = this.store.get(notificationId);
    if (!notification) {
      throw new Error(`Notification not found: ${notificationId}`);
    }
    notification.read = true;
    this.store.set(notificationId, notification);
    return { ...notification };
  }
}

import { IncomingMessage, ServerResponse } from "http";
import { URL } from "url";
import {
  IUserService,
  IProjectService,
  ITaskService,
  ICommentService,
  INotificationService,
  TaskStatus,
} from "./types.js";

// ---------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------

function readBody(req: IncomingMessage): Promise<unknown> {
  return new Promise((resolve, reject) => {
    let raw = "";
    req.on("data", (chunk: Buffer) => {
      raw += chunk.toString();
    });
    req.on("end", () => {
      if (!raw) {
        resolve({});
        return;
      }
      try {
        resolve(JSON.parse(raw));
      } catch {
        reject(new Error("Invalid JSON body"));
      }
    });
    req.on("error", reject);
  });
}

function sendJson(res: ServerResponse, status: number, data: unknown): void {
  const body = JSON.stringify(data, null, 2);
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(body),
  });
  res.end(body);
}

function sendError(res: ServerResponse, status: number, message: string): void {
  sendJson(res, status, { error: message });
}

// ---------------------------------------------------------------
// Router
// ---------------------------------------------------------------

export class Router {
  private userService: IUserService;
  private projectService: IProjectService;
  private taskService: ITaskService;
  private commentService: ICommentService;
  private notificationService: INotificationService;

  constructor(
    userService: IUserService,
    projectService: IProjectService,
    taskService: ITaskService,
    commentService: ICommentService,
    notificationService: INotificationService
  ) {
    this.userService = userService;
    this.projectService = projectService;
    this.taskService = taskService;
    this.commentService = commentService;
    this.notificationService = notificationService;
  }

  async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const baseUrl = `http://${req.headers.host ?? "localhost"}`;
    const url = new URL(req.url ?? "/", baseUrl);
    const pathname = url.pathname.replace(/\/$/, "") || "/";
    const method = req.method ?? "GET";

    try {
      // ── Users ────────────────────────────────────────────────
      if (pathname === "/users" && method === "GET") {
        return sendJson(res, 200, this.userService.getAll());
      }

      if (pathname === "/users" && method === "POST") {
        const body = await readBody(req) as { name: string; email: string };
        return sendJson(res, 201, this.userService.create(body));
      }

      const userMatch = pathname.match(/^\/users\/([^/]+)$/);
      if (userMatch) {
        const id = userMatch[1];
        if (method === "GET") {
          return sendJson(res, 200, this.userService.getById(id));
        }
        if (method === "PUT") {
          const body = await readBody(req) as Partial<{ name: string; email: string }>;
          return sendJson(res, 200, this.userService.update(id, body));
        }
        if (method === "DELETE") {
          this.userService.delete(id);
          return sendJson(res, 204, null);
        }
      }

      // ── Projects ─────────────────────────────────────────────
      if (pathname === "/projects" && method === "GET") {
        return sendJson(res, 200, this.projectService.getAll());
      }

      if (pathname === "/projects" && method === "POST") {
        const body = await readBody(req) as { name: string; description: string };
        return sendJson(res, 201, this.projectService.create(body));
      }

      const projectMatch = pathname.match(/^\/projects\/([^/]+)$/);
      if (projectMatch) {
        const id = projectMatch[1];
        if (method === "GET") {
          return sendJson(res, 200, this.projectService.getById(id));
        }
        if (method === "PUT") {
          const body = await readBody(req) as Partial<{ name: string; description: string }>;
          return sendJson(res, 200, this.projectService.update(id, body));
        }
        if (method === "DELETE") {
          this.projectService.delete(id);
          return sendJson(res, 204, null);
        }
      }

      const projectMembersMatch = pathname.match(/^\/projects\/([^/]+)\/members$/);
      if (projectMembersMatch) {
        const id = projectMembersMatch[1];
        if (method === "POST") {
          const body = await readBody(req) as { userId: string };
          return sendJson(res, 200, this.projectService.addMember(id, body.userId));
        }
        if (method === "DELETE") {
          const body = await readBody(req) as { userId: string };
          return sendJson(res, 200, this.projectService.removeMember(id, body.userId));
        }
      }

      // ── Tasks ────────────────────────────────────────────────
      if (pathname === "/tasks" && method === "GET") {
        const projectId = url.searchParams.get("projectId");
        if (projectId) {
          return sendJson(res, 200, this.taskService.getByProject(projectId));
        }
        return sendError(res, 400, "Missing required query parameter: projectId");
      }

      if (pathname === "/tasks" && method === "POST") {
        const body = await readBody(req) as { title: string; description: string; projectId: string };
        return sendJson(res, 201, this.taskService.create(body));
      }

      const taskStatusMatch = pathname.match(/^\/tasks\/([^/]+)\/status$/);
      if (taskStatusMatch) {
        const id = taskStatusMatch[1];
        if (method === "PUT") {
          const body = await readBody(req) as { status: TaskStatus };
          return sendJson(res, 200, this.taskService.changeStatus(id, body.status));
        }
      }

      const taskAssignMatch = pathname.match(/^\/tasks\/([^/]+)\/assign$/);
      if (taskAssignMatch) {
        const id = taskAssignMatch[1];
        if (method === "PUT") {
          const body = await readBody(req) as { assigneeId: string };
          return sendJson(res, 200, this.taskService.assign(id, body.assigneeId));
        }
      }

      const taskMatch = pathname.match(/^\/tasks\/([^/]+)$/);
      if (taskMatch) {
        const id = taskMatch[1];
        if (method === "GET") {
          return sendJson(res, 200, this.taskService.getById(id));
        }
        if (method === "PUT") {
          const body = await readBody(req) as Partial<{ title: string; description: string }>;
          return sendJson(res, 200, this.taskService.update(id, body));
        }
        if (method === "DELETE") {
          this.taskService.delete(id);
          return sendJson(res, 204, null);
        }
      }

      // ── Comments ─────────────────────────────────────────────
      if (pathname === "/comments" && method === "GET") {
        const taskId = url.searchParams.get("taskId");
        if (taskId) {
          return sendJson(res, 200, this.commentService.getByTask(taskId));
        }
        return sendError(res, 400, "Missing required query parameter: taskId");
      }

      if (pathname === "/comments" && method === "POST") {
        const body = await readBody(req) as { taskId: string; authorId: string; body: string };
        return sendJson(res, 201, this.commentService.create(body));
      }

      const commentMatch = pathname.match(/^\/comments\/([^/]+)$/);
      if (commentMatch) {
        const id = commentMatch[1];
        if (method === "GET") {
          return sendJson(res, 200, this.commentService.getById(id));
        }
        if (method === "DELETE") {
          this.commentService.delete(id);
          return sendJson(res, 204, null);
        }
      }

      // ── Notifications ────────────────────────────────────────
      if (pathname === "/notifications" && method === "GET") {
        const userId = url.searchParams.get("userId");
        if (userId) {
          return sendJson(res, 200, this.notificationService.getByUser(userId));
        }
        return sendError(res, 400, "Missing required query parameter: userId");
      }

      const notificationReadMatch = pathname.match(/^\/notifications\/([^/]+)\/read$/);
      if (notificationReadMatch) {
        const id = notificationReadMatch[1];
        if (method === "PUT") {
          return sendJson(res, 200, this.notificationService.markAsRead(id));
        }
      }

      // ── 404 ──────────────────────────────────────────────────
      return sendError(res, 404, `Route not found: ${method} ${pathname}`);
    } catch (err) {
      const message = err instanceof Error ? err.message : "Internal server error";
      // Use 404 for "not found" errors, 400 for validation errors, 500 otherwise
      if (message.toLowerCase().includes("not found")) {
        return sendError(res, 404, message);
      }
      if (
        message.toLowerCase().includes("invalid") ||
        message.toLowerCase().includes("transition")
      ) {
        return sendError(res, 400, message);
      }
      console.error("[Router] Unexpected error:", err);
      return sendError(res, 500, message);
    }
  }
}

import { createServer } from "http";
import { EventBus } from "./event-bus.js";
import { UserService } from "./services/user-service.js";
import { ProjectService } from "./services/project-service.js";
import { TaskService } from "./services/task-service.js";
import { CommentService } from "./services/comment-service.js";
import { NotificationService } from "./services/notification-service.js";
import { Router } from "./router.js";

const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;

export function createApp() {
  // ── Event Bus ──────────────────────────────────────────────────
  const eventBus = new EventBus();

  // ── Services ───────────────────────────────────────────────────
  const userService = new UserService();
  const projectService = new ProjectService();

  const taskService = new TaskService(eventBus);

  const commentService = new CommentService(
    eventBus,
    // resolveAuthorName: look up the user name without importing UserService directly
    (authorId: string) => {
      try {
        return userService.getById(authorId).name;
      } catch {
        return "Unknown";
      }
    },
    // resolveTaskTitle: look up the task title without importing TaskService directly
    (taskId: string) => {
      try {
        return taskService.getById(taskId).title;
      } catch {
        return "Unknown Task";
      }
    }
  );

  const notificationService = new NotificationService(
    eventBus,
    // resolveTaskAssigneeId: look up the task assignee without importing TaskService directly
    (taskId: string) => {
      try {
        return taskService.getById(taskId).assigneeId;
      } catch {
        return null;
      }
    }
  );

  // ── Router ─────────────────────────────────────────────────────
  const router = new Router(
    userService,
    projectService,
    taskService,
    commentService,
    notificationService
  );

  // ── HTTP Server ────────────────────────────────────────────────
  const server = createServer((req, res) => {
    router.handle(req, res).catch((err) => {
      console.error("[Server] Unhandled error:", err);
      res.writeHead(500, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "Internal server error" }));
    });
  });

  return { server, userService, projectService, taskService, commentService, notificationService };
}

// Only start listening when this is the main module
// (i.e. not imported by demo.ts for its service handles)
if (process.argv[1] && process.argv[1].includes("main")) {
  const { server } = createApp();
  server.listen(PORT, () => {
    console.log(`Task Management API running on http://localhost:${PORT}`);
  });
}

/**
 * Demo script — exercises all features of the Task Management API.
 *
 * Run with: npx tsx src/demo.ts
 *
 * The script starts an HTTP server on a random port, performs a series of
 * HTTP requests that cover every route, validates responses, and then shuts
 * the server down gracefully.
 */

import { createApp } from "./main.js";

// ── Helpers ────────────────────────────────────────────────────────────────

const BASE_URL = "http://localhost:3001";

function log(section: string, msg: string, data?: unknown) {
  const prefix = `\n[${section}]`;
  if (data !== undefined) {
    console.log(prefix, msg, JSON.stringify(data, null, 2));
  } else {
    console.log(prefix, msg);
  }
}

function assert(label: string, condition: boolean, detail?: unknown) {
  if (condition) {
    console.log(`  ✓ ${label}`);
  } else {
    console.error(`  ✗ FAILED: ${label}`, detail ?? "");
    process.exitCode = 1;
  }
}

async function req(
  method: string,
  path: string,
  body?: unknown
): Promise<{ status: number; data: unknown }> {
  const url = `${BASE_URL}${path}`;
  const options: RequestInit = {
    method,
    headers: { "Content-Type": "application/json" },
  };
  if (body !== undefined) {
    options.body = JSON.stringify(body);
  }
  const res = await fetch(url, options);
  let data: unknown;
  try {
    data = await res.json();
  } catch {
    data = null;
  }
  return { status: res.status, data };
}

// ── Main Demo ──────────────────────────────────────────────────────────────

async function runDemo() {
  // Start server
  const { server } = createApp();
  await new Promise<void>((resolve) => server.listen(3001, resolve));
  console.log("=== Task Management API — Demo ===");
  console.log(`Server started on ${BASE_URL}\n`);

  try {
    // ── 1. Users ──────────────────────────────────────────────────────────
    log("Users", "Creating two users...");

    const { status: s1, data: alice } = await req("POST", "/users", {
      name: "Alice",
      email: "alice@example.com",
    });
    assert("Create Alice → 201", s1 === 201);
    assert("Alice has id", typeof (alice as { id: string }).id === "string");
    log("Users", "Alice:", alice);

    const { status: s2, data: bob } = await req("POST", "/users", {
      name: "Bob",
      email: "bob@example.com",
    });
    assert("Create Bob → 201", s2 === 201);
    log("Users", "Bob:", bob);

    const aliceId = (alice as { id: string }).id;
    const bobId = (bob as { id: string }).id;

    // GET all users
    const { status: s3, data: allUsers } = await req("GET", "/users");
    assert("GET /users → 200", s3 === 200);
    assert("Two users exist", (allUsers as unknown[]).length === 2);

    // GET by id
    const { status: s4, data: aliceFetched } = await req("GET", `/users/${aliceId}`);
    assert("GET /users/:id → 200", s4 === 200);
    assert("Alice name matches", (aliceFetched as { name: string }).name === "Alice");

    // PUT update
    const { status: s5, data: aliceUpdated } = await req("PUT", `/users/${aliceId}`, {
      name: "Alice Smith",
    });
    assert("PUT /users/:id → 200", s5 === 200);
    assert("Alice name updated", (aliceUpdated as { name: string }).name === "Alice Smith");

    // ── 2. Projects ───────────────────────────────────────────────────────
    log("Projects", "Creating a project...");

    const { status: p1, data: project } = await req("POST", "/projects", {
      name: "Apollo",
      description: "Mission to the moon",
    });
    assert("Create project → 201", p1 === 201);
    const projectId = (project as { id: string }).id;
    log("Projects", "Project:", project);

    // GET all projects
    const { status: p2, data: allProjects } = await req("GET", "/projects");
    assert("GET /projects → 200", p2 === 200);
    assert("One project exists", (allProjects as unknown[]).length === 1);

    // GET by id
    const { status: p3, data: projectFetched } = await req("GET", `/projects/${projectId}`);
    assert("GET /projects/:id → 200", p3 === 200);
    assert("Project name matches", (projectFetched as { name: string }).name === "Apollo");

    // Add members
    const { status: p4, data: projectWithAlice } = await req(
      "POST",
      `/projects/${projectId}/members`,
      { userId: aliceId }
    );
    assert("Add Alice to project → 200", p4 === 200);
    assert(
      "Alice in memberIds",
      (projectWithAlice as { memberIds: string[] }).memberIds.includes(aliceId)
    );

    const { status: p5, data: projectWithBob } = await req(
      "POST",
      `/projects/${projectId}/members`,
      { userId: bobId }
    );
    assert("Add Bob to project → 200", p5 === 200);
    assert(
      "Both members present",
      (projectWithBob as { memberIds: string[] }).memberIds.length === 2
    );
    log("Projects", "Project with members:", projectWithBob);

    // Remove Bob temporarily and re-add him
    const { status: p6 } = await req("DELETE", `/projects/${projectId}/members`, {
      userId: bobId,
    });
    assert("Remove Bob → 200", p6 === 200);

    await req("POST", `/projects/${projectId}/members`, { userId: bobId });

    // ── 3. Tasks ──────────────────────────────────────────────────────────
    log("Tasks", "Creating tasks...");

    const { status: t1, data: task1 } = await req("POST", "/tasks", {
      title: "Design landing module",
      description: "Create detailed specs for the landing module",
      projectId: projectId,
    });
    assert("Create task → 201", t1 === 201);
    const task1Id = (task1 as { id: string }).id;
    assert("Task status is todo", (task1 as { status: string }).status === "todo");
    log("Tasks", "Task 1:", task1);

    const { status: t2, data: task2 } = await req("POST", "/tasks", {
      title: "Write test plan",
      description: "Document the testing strategy",
      projectId: projectId,
    });
    assert("Create task 2 → 201", t2 === 201);
    const task2Id = (task2 as { id: string }).id;

    // GET by project
    const { status: t3, data: projectTasks } = await req(
      "GET",
      `/tasks?projectId=${projectId}`
    );
    assert("GET /tasks?projectId → 200", t3 === 200);
    assert("Two tasks in project", (projectTasks as unknown[]).length === 2);

    // GET by id
    const { status: t4, data: task1Fetched } = await req("GET", `/tasks/${task1Id}`);
    assert("GET /tasks/:id → 200", t4 === 200);
    assert(
      "Task title matches",
      (task1Fetched as { title: string }).title === "Design landing module"
    );

    // PUT update
    const { status: t5, data: task1Updated } = await req("PUT", `/tasks/${task1Id}`, {
      title: "Design landing module v2",
    });
    assert("PUT /tasks/:id → 200", t5 === 200);
    assert(
      "Task title updated",
      (task1Updated as { title: string }).title === "Design landing module v2"
    );

    // ── 4. Assign tasks ───────────────────────────────────────────────────
    log("Tasks", "Assigning tasks...");

    const { status: a1, data: assignedTask1 } = await req(
      "PUT",
      `/tasks/${task1Id}/assign`,
      { assigneeId: aliceId }
    );
    assert("Assign task1 to Alice → 200", a1 === 200);
    assert(
      "Task1 assigneeId = Alice",
      (assignedTask1 as { assigneeId: string }).assigneeId === aliceId
    );

    const { status: a2 } = await req("PUT", `/tasks/${task2Id}/assign`, {
      assigneeId: bobId,
    });
    assert("Assign task2 to Bob → 200", a2 === 200);

    // ── 5. Status transitions ─────────────────────────────────────────────
    log("Tasks", "Changing task statuses (forward-only state machine)...");

    // todo → in-progress
    const { status: st1, data: inProgress } = await req(
      "PUT",
      `/tasks/${task1Id}/status`,
      { status: "in-progress" }
    );
    assert("todo → in-progress → 200", st1 === 200);
    assert(
      "Status is in-progress",
      (inProgress as { status: string }).status === "in-progress"
    );

    // in-progress → done
    const { status: st2, data: done } = await req("PUT", `/tasks/${task1Id}/status`, {
      status: "done",
    });
    assert("in-progress → done → 200", st2 === 200);
    assert("Status is done", (done as { status: string }).status === "done");

    // Invalid: done → todo (should fail)
    const { status: st3, data: badTransition } = await req(
      "PUT",
      `/tasks/${task1Id}/status`,
      { status: "todo" }
    );
    assert("done → todo → 400 (rejected)", st3 === 400);
    assert("Error message present", typeof (badTransition as { error: string }).error === "string");
    log("Tasks", "Rejected backward transition:", badTransition);

    // Invalid: todo → done (skip, should fail)
    const { status: st4 } = await req("PUT", `/tasks/${task2Id}/status`, {
      status: "done",
    });
    assert("todo → done (skip) → 400 (rejected)", st4 === 400);

    // Advance task2 correctly
    await req("PUT", `/tasks/${task2Id}/status`, { status: "in-progress" });
    const { data: task2Done } = await req("PUT", `/tasks/${task2Id}/status`, { status: "done" });
    assert(
      "task2 correctly advanced to done",
      (task2Done as { status: string }).status === "done"
    );

    // ── 6. Comments ───────────────────────────────────────────────────────
    log("Comments", "Adding comments...");

    const { status: c1, data: comment1 } = await req("POST", "/comments", {
      taskId: task1Id,
      authorId: bobId,
      body: "Great job on the landing module design!",
    });
    assert("Create comment → 201", c1 === 201);
    const comment1Id = (comment1 as { id: string }).id;
    assert("Comment has createdAt", typeof (comment1 as { createdAt: string }).createdAt === "string");
    log("Comments", "Comment 1:", comment1);

    const { status: c2 } = await req("POST", "/comments", {
      taskId: task1Id,
      authorId: aliceId,
      body: "Thanks! I'll start on it next week.",
    });
    assert("Create comment 2 → 201", c2 === 201);

    // GET by task
    const { status: c3, data: taskComments } = await req(
      "GET",
      `/comments?taskId=${task1Id}`
    );
    assert("GET /comments?taskId → 200", c3 === 200);
    assert("Two comments on task", (taskComments as unknown[]).length === 2);

    // GET by id
    const { status: c4, data: comment1Fetched } = await req(
      "GET",
      `/comments/${comment1Id}`
    );
    assert("GET /comments/:id → 200", c4 === 200);
    assert(
      "Comment body matches",
      (comment1Fetched as { body: string }).body === "Great job on the landing module design!"
    );

    // DELETE comment
    const { status: c5 } = await req("DELETE", `/comments/${comment1Id}`);
    assert("DELETE /comments/:id → 204", c5 === 204);

    const { data: remainingComments } = await req("GET", `/comments?taskId=${task1Id}`);
    assert("One comment remains", (remainingComments as unknown[]).length === 1);

    // ── 7. Notifications ─────────────────────────────────────────────────
    log("Notifications", "Checking notifications...");

    // Alice was assigned task1 → should have "Task '...' assigned to you"
    // Alice's task1 was moved to in-progress, done → should have status-change notifications
    // Bob commented on task1 (assigned to Alice) → Alice should get a comment notification
    const { status: n1, data: aliceNotifs } = await req(
      "GET",
      `/notifications?userId=${aliceId}`
    );
    assert("GET /notifications?userId → 200", n1 === 200);
    const aliceNotifList = aliceNotifs as Array<{
      id: string;
      message: string;
      read: boolean;
    }>;
    log("Notifications", `Alice has ${aliceNotifList.length} notification(s):`, aliceNotifList);
    assert("Alice has notifications", aliceNotifList.length > 0);

    const assignedNotif = aliceNotifList.find((n) => n.message.includes("assigned to you"));
    assert("Alice got task-assigned notification", assignedNotif !== undefined);

    const statusNotif = aliceNotifList.find((n) =>
      n.message.includes("status changed to")
    );
    assert("Alice got status-change notification", statusNotif !== undefined);

    const commentNotif = aliceNotifList.find((n) => n.message.includes("commented on task"));
    assert("Alice got comment notification", commentNotif !== undefined);

    // Bob should have task-assigned and status-change notifications for task2
    const { data: bobNotifs } = await req("GET", `/notifications?userId=${bobId}`);
    const bobNotifList = bobNotifs as Array<{ id: string; message: string; read: boolean }>;
    log("Notifications", `Bob has ${bobNotifList.length} notification(s):`, bobNotifList);
    assert("Bob has notifications", bobNotifList.length > 0);

    // Mark a notification as read
    if (aliceNotifList.length > 0) {
      const notifId = aliceNotifList[0].id;
      const { status: n2, data: readNotif } = await req(
        "PUT",
        `/notifications/${notifId}/read`
      );
      assert("PUT /notifications/:id/read → 200", n2 === 200);
      assert("Notification marked as read", (readNotif as { read: boolean }).read === true);
      log("Notifications", "Marked as read:", readNotif);
    }

    // ── 8. Error cases ────────────────────────────────────────────────────
    log("Errors", "Verifying error handling...");

    const { status: e1 } = await req("GET", "/users/non-existent-id");
    assert("GET unknown user → 404", e1 === 404);

    const { status: e2 } = await req("GET", "/projects/non-existent-id");
    assert("GET unknown project → 404", e2 === 404);

    const { status: e3 } = await req("GET", "/tasks/non-existent-id");
    assert("GET unknown task → 404", e3 === 404);

    const { status: e4 } = await req("GET", "/tasks");
    assert("GET /tasks without projectId → 400", e4 === 400);

    const { status: e5 } = await req("GET", "/unknown-route");
    assert("Unknown route → 404", e5 === 404);

    // ── 9. Cleanup / DELETE ───────────────────────────────────────────────
    log("Cleanup", "Deleting resources...");

    const { status: d1 } = await req("DELETE", `/projects/${projectId}`);
    assert("DELETE /projects/:id → 204", d1 === 204);

    const { data: afterDelete } = await req("GET", "/projects");
    assert("No projects remain", (afterDelete as unknown[]).length === 0);

    const { status: d2 } = await req("DELETE", `/users/${aliceId}`);
    assert("DELETE /users/:id (Alice) → 204", d2 === 204);

    const { status: d3 } = await req("DELETE", `/users/${bobId}`);
    assert("DELETE /users/:id (Bob) → 204", d3 === 204);

    const { data: afterUserDelete } = await req("GET", "/users");
    assert("No users remain", (afterUserDelete as unknown[]).length === 0);

    console.log("\n=== Demo complete ===\n");
  } finally {
    await new Promise<void>((resolve, reject) =>
      server.close((err) => (err ? reject(err) : resolve()))
    );
    console.log("Server stopped.");
  }
}

runDemo().catch((err) => {
  console.error("Demo failed with unexpected error:", err);
  process.exit(1);
});

